/**
 * Errors surfaced across the FFI boundary.
 *
 * Kept separate from `EngineError` because UniFFI error types must be
 * `Clone` (git2 errors are not). Every variant carries `corruption`, set from
 * `EngineError::is_corruption_error`, so host apps can route corrupt-repo
 * failures into the repair flow.
 */
public 
enum BridgeError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Git(message: String, corruption: Bool
    )
    case Io(message: String, corruption: Bool
    )
    case Invalid(message: String, corruption: Bool
    )
    case Busy(message: String, corruption: Bool
    )
    case NotARepository(path: String, corruption: Bool
    )
    case Unsupported(message: String, corruption: Bool
    )
    case Other(message: String, corruption: Bool
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension BridgeError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBridgeError: FfiConverterRustBuffer {
    typealias SwiftType = BridgeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BridgeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Git(
            message: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )
        case 2: return .Io(
            message: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )
        case 3: return .Invalid(
            message: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )
        case 4: return .Busy(
            message: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )
        case 5: return .NotARepository(
            path: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )
        case 6: return .Unsupported(
            message: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )
        case 7: return .Other(
            message: try FfiConverterString.read(from: &buf), 
            corruption: try FfiConverterBool.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BridgeError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Git(message,corruption):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        
        case let .Io(message,corruption):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        
        case let .Invalid(message,corruption):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        
        case let .Busy(message,corruption):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        
        case let .NotARepository(path,corruption):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(path, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        
        case let .Unsupported(message,corruption):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        
        case let .Other(message,corruption):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            FfiConverterBool.write(corruption, into: &buf)
            
        }
    }
}


