/**
 * How a credential should be resolved for a git operation.
 */

public enum CredentialSource: Equatable, Hashable {
    
    /**
     * No credentials; only works for anonymous/public endpoints.
     */
    case none
    /**
     * HTTPS basic auth: PAT or OAuth token used as the password.
     */
    case userPass(username: String, password: String
    )
    /**
     * SSH keypair, loaded from memory (private key PEM text).
     */
    case sshKey(username: String, privateKey: String, publicKey: String?, passphrase: String?
    )
    /**
     * Let libgit2 try its default paths (ssh agent, config, credential helpers).
     */
    case `default`
    /**
     * GitHub OAuth access token — used as a bearer for HTTPS auth.
     */
    case gitHubOAuth(token: String
    )
    /**
     * GitHub App installation token scoped to selected repositories.
     */
    case gitHubAppInstallation(token: String
    )





}

#if compiler(>=6)
extension CredentialSource: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCredentialSource: FfiConverterRustBuffer {
    typealias SwiftType = CredentialSource

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CredentialSource {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .userPass(username: try FfiConverterString.read(from: &buf), password: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .sshKey(username: try FfiConverterString.read(from: &buf), privateKey: try FfiConverterString.read(from: &buf), publicKey: try FfiConverterOptionString.read(from: &buf), passphrase: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 4: return .`default`
        case 5: return .gitHubOAuth(token: try FfiConverterString.read(from: &buf)
        )
        case 6: return .gitHubAppInstallation(token: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CredentialSource, into buf: inout [UInt8]) {
        switch value {
        
        
        case .none:
            writeInt(&buf, Int32(1))
        
        
        case let .userPass(username,password):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(username, into: &buf)
            FfiConverterString.write(password, into: &buf)
            
        
        case let .sshKey(username,privateKey,publicKey,passphrase):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(username, into: &buf)
            FfiConverterString.write(privateKey, into: &buf)
            FfiConverterOptionString.write(publicKey, into: &buf)
            FfiConverterOptionString.write(passphrase, into: &buf)
            
        
        case .`default`:
            writeInt(&buf, Int32(4))
        case let .gitHubOAuth(token):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(token, into: &buf)
        case let .gitHubAppInstallation(token):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(token, into: &buf)
        
        }
    }
}


